"""Text is never generated by an image model (it comes out garbled). Subtitles, title and end card
are drawn here with bundled OFL fonts, so the result is identical on any machine."""
from __future__ import annotations

import textwrap
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

from .common import ROOT

FONTS = ROOT / "assets" / "fonts"
ASPECTS = {"9x16": (1080, 1920), "16x9": (1920, 1080)}


def font(size: int, ethiopic: bool = False, weight: str = "SemiBold") -> ImageFont.FreeTypeFont:
    f = ImageFont.truetype(str(FONTS / ("NotoSansEthiopic.ttf" if ethiopic else "NotoSans.ttf")), size)
    try:
        f.set_variation_by_name(weight)
    except Exception:
        pass
    return f


def wrap_subtitle(text: str, width: int = 40) -> list[list[str]]:
    """Split into cards of at most two lines of ~40 characters."""
    lines = textwrap.wrap(text, width=width)
    return [lines[i:i + 2] for i in range(0, len(lines), 2)]


def subtitle_png(lines: list[str], aspect: str, path: Path) -> None:
    W, H = ASPECTS[aspect]
    img = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    f = font(54 if aspect == "9x16" else 50)
    # vertical: keep clear of the bottom ~22% where TikTok/Reels put captions and buttons
    base_y = int(H * (0.70 if aspect == "9x16" else 0.86))
    lh = int(f.size * 1.3)
    y0 = base_y - lh * (len(lines) - 1)
    for i, line in enumerate(lines):
        w = d.textlength(line, font=f)
        x, y = (W - w) / 2, y0 + i * lh
        pad = 14
        d.rounded_rectangle([x - pad, y - 6, x + w + pad, y + lh - 4], radius=10, fill=(0, 0, 0, 150))
        d.text((x, y), line, font=f, fill=(255, 255, 255, 255))
    img.save(path)


def title_png(title_am: str, title_en: str, aspect: str, path: Path) -> None:
    W, H = ASPECTS[aspect]
    img = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    fa, fe = font(170, ethiopic=True, weight="Bold"), font(56, weight="Regular")
    for txt, f, y in ((title_am, fa, H * 0.36), (title_en.upper(), fe, H * 0.36 + 230)):
        w = d.textlength(txt, font=f)
        d.text(((W - w) / 2 + 3, y + 3), txt, font=f, fill=(0, 0, 0, 160))
        d.text(((W - w) / 2, y), txt, font=f, fill=(247, 236, 214, 255))
    img.save(path)


def end_card_png(lines_am: list[str], lines_en: list[str], aspect: str, path: Path) -> None:
    W, H = ASPECTS[aspect]
    img = Image.new("RGB", (W, H), (12, 18, 22))
    d = ImageDraw.Draw(img)
    fa = font(60 if aspect == "9x16" else 54, ethiopic=True, weight="Medium")
    fe = font(40 if aspect == "9x16" else 36, weight="Regular")
    fb = font(46, ethiopic=True, weight="Bold")
    rows = []
    for am, en in zip(lines_am, lines_en):
        for t in textwrap.wrap(am, 26 if aspect == "9x16" else 44):
            rows.append((t, fa, (247, 236, 214)))
        for t in textwrap.wrap(en, 40 if aspect == "9x16" else 70):
            rows.append((t, fe, (170, 190, 195)))
        rows.append(("", fe, None))
    rows.append(("AI-GENERATED  ·  በAI የተሠራ", fb, (233, 180, 90)))
    total = sum(int(f.size * 1.45) for _, f, _ in rows)
    y = (H - total) / 2
    for t, f, c in rows:
        if t:
            w = d.textlength(t, font=f)
            d.text(((W - w) / 2, y), t, font=f, fill=c)
        y += int(f.size * 1.45)
    img.save(path)
